import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ApiService, Extra } from '../../../../services/api';
import { Observable, Subscription } from 'rxjs';

@Component({
  selector: 'app-extras',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslateModule],
  templateUrl: './extras.component.html',
  styleUrls: ['./extras.component.css']
})
export class ExtrasComponent implements OnInit, OnDestroy {
  showFullProjects = false;
  $extras: Observable<Extra> = new Observable();
  private langChangeSubscription?: Subscription;

  constructor(
    private translate: TranslateService,
    private apiService: ApiService
  ) {}

  ngOnInit() {
    this.loadExtras();

    // Recargar cuando el idioma cambie
    this.langChangeSubscription = this.translate.onLangChange.subscribe(() => {
      this.loadExtras();
    });
  }

  ngOnDestroy() {
    if (this.langChangeSubscription) {
      this.langChangeSubscription.unsubscribe();
    }
  }

  loadExtras() {
    this.$extras = this.apiService.getExtras();
  }

  toggleFullProjects() {
    this.showFullProjects = !this.showFullProjects;
  }

  changeLang(language: string) {
    this.translate.use(language);
  }
}
<section id="extras-section">
  <div class="extras-card">
    <h2>{{ 'EXTRAS.TITLE' | translate }}</h2>

    <div *ngIf="$extras | async as extras" class="extras-list">

      <!-- Intereses -->
      <div class="extras-item">
        <h3>🎯 {{ extras.INTERESTS.TITLE }}</h3>
        <p>{{ extras.INTERESTS.TEXT }}</p>
      </div>

      <!-- Idiomas -->
      <div class="extras-item">
        <h3>🌍 {{ extras.LANGUAGES.TITLE }}</h3>
        <p><strong>{{ extras.LANGUAGES.SPANISH }}:</strong> {{ extras.LANGUAGES.LEVEL.SPANISH }}</p>
        <p><strong>{{ extras.LANGUAGES.ENGLISH }}:</strong> {{ extras.LANGUAGES.LEVEL.ENGLISH }}</p>
      </div>

      <!-- EVENTOS -->
      <div class="extras-item">
        <h3>🎉 {{ extras.EVENTS }}</h3>
        <ul>
          <li *ngFor="let event of extras.EVENTS_LIST">{{ event }}</li>
        </ul>
      </div>

      <!-- Reconocimientos -->
      <div class="extras-item">
        <h3>🏆 {{ extras.RECOGNITIONS.TITLE }}</h3>
        <p>{{ extras.RECOGNITIONS.TEXT }}</p>
      </div>

      <!-- Certificados -->
      <div class="extras-item">
        <h3>📜 {{ extras.CERTIFICATES }}</h3>
        <ul>
          <li *ngFor="let cert of extras.CERTIFICATES_LIST">{{ cert }}</li>
        </ul>
      </div>

    </div>
  </div>
</section>
